<form class="filters" method="get"><input class="input" name="q" value="<?= e((string)input('q')) ?>" placeholder="Κωδικός" style="max-width:220px;min-height:44px" aria-label="Κωδικός"><select name="status" aria-label="Κατάσταση"><option value="">Όλοι</option><?php foreach (['active', 'redeemed', 'expired', 'void'] as $k): ?><option value="<?= $k ?>" <?= input('status') === $k ? 'selected' : '' ?>><?= e(code_status_label($k)) ?></option><?php endforeach ?></select><button class="btn sm dark">Φίλτρο</button><a class="btn sm ghost" href="/admin/export/codes.csv">CSV</a></form>
<?php if ($rows): ?><div class="table-wrap"><table class="t"><thead><tr><th>Κωδικός</th><th>Υπηρεσία</th><th>Επιχείρηση</th><th>Πελάτης</th><th>Λήξη</th><th>Κατάσταση</th></tr></thead><tbody>
<?php foreach ($rows as $c): ?><tr><td class="mono"><?= e($c['code']) ?></td><td><?= e($c['title']) ?></td><td><?= e($c['business']) ?></td><td class="small"><?= e($c['email']) ?></td><td><?= e(date_gr($c['expires_at'])) ?></td><td><span class="badge badge-<?= e($c['status']) ?>"><?= e(code_status_label($c['status'])) ?></span><?= $c['redeemed_at'] ? '<br><span class="small muted">' . e(date_gr($c['redeemed_at'], true)) . '</span>' : '' ?></td></tr><?php endforeach ?>
</tbody></table></div><?php else: ?><div class="empty"><b>Κανένας κωδικός</b></div><?php endif ?>
